      const normalized = normalizeKeybinds(log, WS.meta && WS.meta.appearancePresets);
      WS.meta.keybinds = normalized.bindings;
      const normalizedGrid = normalizeGridKeybinds(log);
      WS.meta.gridKeybinds = normalizedGrid.bindings;
